@startuml

class Customer {
  + name : string
  + address : string
}

class Account {
  + balance : double
}

class SavingsAccount extends Account {
  + interestRate : double
}

class InvestmentAccount extends Account {}

class StockOrder {
  + quantity : int
  + price : double
  + ticker : string
  + commission : double
}

Customer "1" -- "*" Account
InvestmentAccount "1" -- "*" StockOrder

@enduml

